language sql stable
as $$
  select exists (
    select 1
    from public.board_members
    where board_id = p_board_id and user_id = auth.uid() and role = 'editor'
  );
$$;

create function public.board_is_not_archived(p_board_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.boards
    where id = p_board_id and is_archived = false
  );
$$;

create function public.can_manage_cards_on_board(p_board_id bigint) returns boolean
language sql stable
as $$
  select public.is_board_editor(p_board_id) and public.board_is_not_archived(p_board_id);
$$;

create policy boards_select on public.boards
for select to authenticated
using (public.is_board_member(id));

