  public.can_manage_cards_on_board(board_id)
  and (assignee_id is null or public.is_board_member(
    (select board_id from public.cards where id = new.id)
  ))
);

create policy cards_delete on public.cards
for delete to authenticated
using (
  public.can_manage_cards_on_board(board_id)
  and public.board_is_not_archived(board_id)
);
