create or replace function public.is_resident(p_unit_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.is_building_staff(p_building_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.unit_building_id(p_unit_id bigint)
returns bigint
language sql
stable
as $$
  select u.building_id
  from public.units u
  where u.id = p_unit_id
  limit 1;
$$;

create policy units_select on public.units
  for select to authenticated
  using (
    public.is_resident(id)
    or public.is_building_staff(public.unit_building_id(id))
  );

create policy residents_select on public.residents
  for select to authenticated
  using (
    user_id = auth.uid()
    or public.is_building_staff(public.unit_building_id(unit_id))
  );

create policy requests_select on public.requests
  for select to authenticated
  using (
    public.is_resident(unit_id)
    or public.is_building_staff(public.unit_building_id(unit_id))
  );

create policy requests_insert on public.requests
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and status = 'open'
    and public.is_resident(unit_id)
  );

create policy requests_update on public.requests
  for update to authenticated
  using (
    public.is_resident(unit_id)
    or public.is_building_staff(public.unit_building_id(unit_id))
  )
  with check (
    public.is_resident(unit_id)
    or public.is_building_staff(public.unit_building_id(unit_id))
  );

create policy request_photos_select on public.request_photos
  for select to authenticated
  using (
    public.is_resident(
      (select u.unit_id from public.requests u where u.id = request_id)
    )
    or public.is_building_staff(
      (select u.building_id from public.requests u where u.id = request_id)
    )
  );

create policy request_photos_insert on public.request_photos
  for insert to authenticated
  with check (
