```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy auctions_select on public.auctions
  for select to authenticated
  using (true);

create policy bids_select on public.bids
  for select to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_increment numeric;
  v_result numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = auth.uid() then
    raise exception 'seller cannot bid on own auction';
  end if;

  if p_amount is null then
    raise exception 'invalid bid amount';
  end if;

  if v_auction.highest_bid is null then
    v_increment := v_auction.min_increment;
    v_highest := p_amount;
  else
    v_increment := v_auction.min_increment;
    v_highest := v_auction.highest_bid + v_increment;
  end if;

  if p_amount < v_highest then
    raise exception 'bid too low';
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (v_auction.id, auth.uid(), p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = v_auction.id;

  return p_amount;
end;
$$;
```

